/** Generated from the overhaul textbook. Re-run tools/import-overhaul-courses.mjs. Do not edit by hand. */
export default {"id":"launchkey-level-7","number":7,"title":"Continuous Encoders, Faders & DAW Control Surface","skillBand":"Textbook","duration":"From the course textbook","summary":"The 8 continuous rotary encoders on the Launchkey MK4 61 provide hardware parameter control across eight discrete operational modes. Four modes are native, bidirectional DAW control surfaces, while four modes are user-programmable standalon","modules":[{"id":"launchkey-m-7-1-1","code":"7.1","title":"Continuous Encoders, Faders & DAW Control Surface","blurb":"The 8 continuous rotary encoders on the Launchkey MK4 61 provide hardware parameter control across eight discrete operational modes. Four modes are native, bidirectional DAW control surfaces, while four modes are user-programmable standalon","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-19","title":"Section overview","blocks":[{"type":"step","title":"Section 7.1 — Continuous Rotary Encoder Operational Modes","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"The 8 continuous rotary encoders on the Launchkey MK4 61 provide hardware parameter control across eight discrete operational modes. Four modes are native, bidirectional DAW control surfaces, while four modes are user-programmable standalone Custom Modes. This module details mode selection, visual LED telemetry, parameter banking, and host disconnection states."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Execute encoder mode selection using the <code>Shift + Pads 1–8</code> command matrix.","Formulate the operational roles of the four DAW-native modes: <strong>Plugin</strong>, <strong>Mixer</strong>, <strong>Sends</strong>, and <strong>Transport</strong>.","Formulate the architecture of <strong>Custom Modes 1–4</strong> across their two 8-parameter pages.","Interpret the three-tier pink LED telemetry for encoder modes (Active, Available, Unavailable).","Diagnose encoder behavior during DAW host disconnection."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-7-1-1","title":"7.1.1: Encoder Mode Selection Matrix","blocks":[{"type":"step","title":"7.1.1: Encoder Mode Selection Matrix","blocks":[{"type":"prose","html":"Encoder modes are selected using the top row of RGB pads (Pads 1–8) while holding <code>Shift</code>:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    ENCODER MODE SELECTION (SHIFT + PADS 1–8)                  |\n+-------+---------------+-----------------+-------------------------------------+\n| Pad # | Encoder Mode  | Operational Tier| Functional Scope                    |\n+-------+---------------+-----------------+-------------------------------------+\n| **1** | **Plugin**    | DAW Mode Only   | 8 parameters of focused DAW device  |\n| **2** | **Mixer**     | DAW Mode Only   | Track Pan / Volume across 8 tracks  |\n| **3** | **Sends**     | DAW Mode Only   | Send A / Send B level across 8 tracks|\n| **4** | **Transport** | DAW Mode Only   | Timeline Scrub, Zoom, Loop, Markers |\n+-------+---------------+-----------------+-------------------------------------+\n| **5** | **Custom 1**  | Always Available| User-defined CC / NRPN (Page 1 &amp; 2) |\n| **6** | **Custom 2**  | Always Available| User-defined CC / NRPN (Page 1 &amp; 2) |\n| **7** | **Custom 3**  | Always Available| User-defined CC / NRPN (Page 1 &amp; 2) |\n| **8** | **Custom 4**  | Always Available| User-defined CC / NRPN (Page 1 &amp; 2) |\n+-------+---------------+-----------------+-------------------------------------+</pre>"}]}],"minutes":8},{"id":"launchkey-l-7-1-2","title":"7.1.2: Encoder Mode Optical Telemetry (Pink LED Architecture)","blocks":[{"type":"step","title":"7.1.2: Encoder Mode Optical Telemetry (Pink LED Architecture)","blocks":[{"type":"prose","html":"When <code>Shift</code> is held down, Pads 1–8 provide instant visual feedback regarding encoder mode availability using a dedicated <strong>Pink</strong> color palette:"},{"type":"list","items":["<strong>Bright Solid Pink</strong>: Indicates the <strong>currently active</strong> encoder mode.","<strong>Dim Pink</strong>: Indicates a mode that is <strong>available for selection</strong>.","<strong>Unlit / Extinguished</strong>: Indicates a mode that is <strong>unavailable</strong> (e.g., Pads 1–4 when no DAW is connected)."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-7-1-3","title":"7.1.3: Deep Analysis of DAW-Native Modes","blocks":[{"type":"step","title":"7.1.3: Deep Analysis of DAW-Native Modes","blocks":[{"type":"list","items":["<strong>Plugin Mode (Pad 1)</strong>:","Encoders 1–8 map to the 8 macro parameters of the currently focused virtual instrument or audio effect.","<code>Encoder Bank Up / Down</code>: Navigates to additional parameter banks (e.g., Parameters 9–16, 17–24).","<code>Shift + Encoder Bank Up / Down</code>: Steps sequentially through adjacent devices on the track device chain.","<strong>Mixer Mode (Pad 2)</strong>:","Encoders 1–8 control Track Pan for the currently focused 8-track bank.","<strong>Sends Mode (Pad 3)</strong>:","Encoders 1–8 control Send A levels for the current 8 tracks. Pressing <code>Encoder Bank Up / Down</code> toggles control to Send B, Send C, etc.","<strong>Transport Mode (Pad 4)</strong>:","Maps encoders to DAW transport scrub, zoom, marker navigation, and tempo (host-specific maps covered in Modules 13 and 16)."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-7-1-4","title":"7.1.4: Custom Modes 1–4 Architecture","blocks":[{"type":"step","title":"7.1.4: Custom Modes 1–4 Architecture","blocks":[{"type":"prose","html":"In Custom Modes 1–4 (Pads 5–8):"},{"type":"list","items":["Each mode stores <strong>16 independent rotary parameters</strong> organized into <strong>2 pages of 8 encoders</strong>.","Pressing <code>Encoder Bank Up</code> moves from Page 1 (Controls 1–8) to Page 2 (Controls 9–16).","OLED screen displays custom 16-character parameter labels defined in Novation Components."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-7-1-5","title":"7.1.5: Host Disconnection State","blocks":[{"type":"step","title":"7.1.5: Host Disconnection State","blocks":[{"type":"prose","html":"When the Launchkey MK4 61 is operating standalone (connected to hardware synths via 5-pin DIN or powered via USB without a DAW running):"},{"type":"list","items":["Pads 1–4 (Plugin, Mixer, Sends, Transport) <strong>remain completely unlit</strong> and cannot be selected.","The controller automatically locks encoder operation to <strong>Custom Modes 1–4</strong>."],"ordered":false}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: Mode selection matrix (<code>Shift + Pads 1–8</code>); 4 DAW modes vs 4 Custom modes; 3-tier pink LED telemetry; 2-page Custom architecture; host disconnection behavior.","<strong>mustNotCover</strong>: Invention of undocumented 9th encoder modes."],"ordered":false}]},{"type":"step","title":"Practical Guided Task & Assessment Checkpoint","blocks":[{"type":"prose","html":"<strong>Task</strong>: Hold <code>Shift</code> and inspect Pads 1–8. Switch to Mixer Mode (Pad 2), verify the bright pink LED, switch to Custom 1 (Pad 5), and cycle between Page 1 and Page 2 using <code>Encoder Bank Up / Down</code>."},{"type":"prose","html":"<strong>Checkpoint Validation</strong>:"},{"type":"list","items":["Shift-held pad illumination confirms bright pink on the active mode and dim pink on available modes.","Page navigation alternates between Controls 1–8 and Controls 9–16 in Custom 1."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"launchkey-m-7-2-2","code":"7.2","title":"Continuous Encoders, Faders & DAW Control Surface","blurb":"The 9 linear 45 mm faders and 9 tactile fader buttons on the Launchkey MK4 61 provide precise multi-channel mixing and multi-parameter continuous control. This module covers fader mode selection, DAW Volume mode architecture (including the ","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-20","title":"Section overview","blocks":[{"type":"step","title":"Section 7.2 — Linear Fader Operational Modes","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"The 9 linear 45 mm faders and 9 tactile fader buttons on the Launchkey MK4 61 provide precise multi-channel mixing and multi-parameter continuous control. This module covers fader mode selection, DAW Volume mode architecture (including the 9th Master fader), the Button 9 Select/Arm toggle, and standalone Custom Fader modes."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Execute fader mode switching using the <code>Shift + Fader Buttons 1–5</code> protocol.","Formulate the channel architecture of DAW Volume mode across Faders 1–8 and Master Fader 9.","Execute the Select versus Arm toggle using Fader Button 9.","Detail the behavior of Fader Buttons 1–8 in DAW mode versus Custom Modes."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-7-2-1","title":"7.2.1: Fader Mode Selection Matrix","blocks":[{"type":"step","title":"7.2.1: Fader Mode Selection Matrix","blocks":[{"type":"prose","html":"Fader operational modes are selected by holding <code>Shift</code> and pressing one of the first five <strong>Fader Buttons</strong>:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                 FADER MODE SELECTION (SHIFT + FADER BUTTONS 1–5)              |\n+---------------+---------------+-----------------+-----------------------------+\n| Fader Button  | Fader Mode    | Operational Tier| Functional Scope            |\n+---------------+---------------+-----------------+-----------------------------+\n| **Button 1**  | **Volume**    | DAW Mode Only   | Faders 1–8: Tracks 1–8 Vol  |\n|               |               |                 | Fader 9: Master Track Vol   |\n+---------------+---------------+-----------------+-----------------------------+\n| **Button 2**  | **Custom 1**  | Always Available| User-defined Faders/Buttons |\n| **Button 3**  | **Custom 2**  | Always Available| User-defined Faders/Buttons |\n| **Button 4**  | **Custom 3**  | Always Available| User-defined Faders/Buttons |\n| **Button 5**  | **Custom 4**  | Always Available| User-defined Faders/Buttons |\n+---------------+---------------+-----------------+-----------------------------+</pre>"}]}],"minutes":8},{"id":"launchkey-l-7-2-2","title":"7.2.2: DAW Volume Mode & Master Fader 9","blocks":[{"type":"step","title":"7.2.2: DAW Volume Mode & Master Fader 9","blocks":[{"type":"prose","html":"In DAW Volume Mode (Button 1):"},{"type":"list","items":["<strong>Faders 1–8</strong>: Control the track volume faders of the currently focused 8-channel DAW mixer bank.","<strong>Fader 9 (The 9th Fader)</strong>: Operates as the <strong>Dedicated Main / Master Output Volume</strong> fader.","<strong>OLED Feedback</strong>: Moving any fader generates an immediate decibel popup displaying the track name and volume (e.g., <code>Trk 1 Volume: -4.2 dB</code> or <code>Master Vol: 0.0 dB</code>)."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-7-2-3","title":"7.2.3: Fader Button 9 (Select vs. Arm Toggle)","blocks":[{"type":"step","title":"7.2.3: Fader Button 9 (Select vs. Arm Toggle)","blocks":[{"type":"prose","html":"In DAW Volume Mode, Fader Buttons 1–8 have two distinct operational states, toggled by <strong>Fader Button 9</strong>:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">                  FADER BUTTON 9 OPERATIONAL TOGGLE\n+-------------------------------------------------------------------------------+\n| MODE A: TRACK SELECT (Button 9 LED Unlit / Off)                               |\n| - Buttons 1–8 illuminate in their respective DAW Track Colors.                |\n| - Pressing a button selects and focuses that track in the DAW mixer.          |\n+-------------------------------------------------------------------------------+\n| MODE B: TRACK ARM (Button 9 LED Illuminated Red)                              |\n| - Buttons 1–8 function as Track Record Arm toggles.                           |\n| - Unarmed tracks show Dim Red; Armed tracks show Bright Flashing Red.         |\n+-------------------------------------------------------------------------------+</pre>"}]}],"minutes":8},{"id":"launchkey-l-7-2-4","title":"7.2.4: Fader Buttons in Custom Modes 1–4","blocks":[{"type":"step","title":"7.2.4: Fader Buttons in Custom Modes 1–4","blocks":[{"type":"prose","html":"When operating in Custom Modes 1–4:"},{"type":"list","items":["Fader Buttons 1–9 follow the programming assigned in Novation Components.","Supported message types include: MIDI Note On/Off, Control Change (CC), Program Change, NRPN, Computer Keystroke shortcuts, or <code>No Control</code> (disabled).","Buttons can be configured as <strong>Momentary</strong> (active while held) or <strong>Toggle</strong> (alternates on/off state per press)."],"ordered":false}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: Fader mode selection (<code>Shift + Fader Buttons 1–5</code>); DAW Volume mode (1–8 tracks, 9 master); Fader Button 9 Select/Arm toggle; Custom Fader Modes 1–4.","<strong>mustNotCover</strong>: Claiming 25/37 Launchkey models have physical faders."],"ordered":false}]},{"type":"step","title":"Practical Guided Task & Assessment Checkpoint","blocks":[{"type":"prose","html":"<strong>Task</strong>: In an active DAW session, switch faders to Volume Mode. Move Fader 9 to confirm Master volume control. Press Fader Button 9 to toggle between Track Select (track colors) and Track Arm (red LEDs)."},{"type":"prose","html":"<strong>Checkpoint Validation</strong>:"},{"type":"list","items":["Fader 9 controls DAW Master output volume.","Fader Button 9 successfully alternates Fader Buttons 1–8 between Select and Arm states."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"launchkey-m-7-3-3","code":"7.3","title":"Continuous Encoders, Faders & DAW Control Surface","blurb":"The dedicated transport and workflow buttons on the Launchkey MK4 61 provide tactile command of the host DAW without requiring mouse or computer keyboard interaction. This module details the operational protocols governing playback, timelin","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-21","title":"Section overview","blocks":[{"type":"step","title":"Section 7.3 — Hardware Transport & Studio Workflow Controls","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"The dedicated transport and workflow buttons on the Launchkey MK4 61 provide tactile command of the host DAW without requiring mouse or computer keyboard interaction. This module details the operational protocols governing playback, timeline navigation, recording targets, retrospective capture, real-time quantization, multi-tier undo/redo, and metronome synchronization."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Detail the multi-state operational protocol of the four transport buttons: <strong>Play</strong>, <strong>Stop</strong>, <strong>Record</strong>, and <strong>Loop</strong>.","Formulate the double-press Return-to-Zero behavior of the physical <code>Stop</code> button.","Contrast Session View recording versus Arrangement View recording execution via the hardware <code>Record</code> button.","Execute retrospective recording via <code>Capture MIDI</code>.","Apply host timing alignment via the dedicated <code>Quantise</code> button.","Execute <code>Undo</code> and <code>Redo</code> (<code>Shift + Undo</code>) from the hardware.","Toggle DAW click synchronization via the <code>Metronome</code> button."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-7-3-1","title":"7.3.1: Master Transport Execution Matrix","blocks":[{"type":"step","title":"7.3.1: Master Transport Execution Matrix","blocks":[{"type":"prose","html":"The lower-right transport cluster provides direct access to core DAW engine states:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    MASTER TRANSPORT PROTOCOL MATRIX                           |\n+-------------------+---------------------+-------------------------------------+\n| Hardware Button   | Primary Action      | Shift-Secondary Action              |\n+-------------------+---------------------+-------------------------------------+\n| **[ PLAY ]**      | Start DAW Playback  | **Pause / Continue** Playback       |\n+-------------------+---------------------+-------------------------------------+\n| **[ STOP ]**      | Halt DAW Playback   | *(Double-press: Return to 1.1.1)*   |\n+-------------------+---------------------+-------------------------------------+\n| **[ RECORD ]**    | Engage DAW Record   | Context-Dependent Target            |\n+-------------------+---------------------+-------------------------------------+\n| **[ LOOP ]**      | Toggle Loop Bracket | None                                |\n+-------------------+---------------------+-------------------------------------+</pre>"}]}],"minutes":8},{"id":"launchkey-l-7-3-2","title":"7.3.2: The Double-Press Stop (Return to Zero) Protocol","blocks":[{"type":"step","title":"7.3.2: The Double-Press Stop (Return to Zero) Protocol","blocks":[{"type":"prose","html":"The physical <code>Stop</code> button features a two-stage timeline execution rule:"},{"type":"list","items":["<strong>First Press</strong>: Halts host playback immediately at the current playhead position.","<strong>Second Press</strong>: Instantly rewinds the DAW playhead back to the absolute beginning of the project (<strong>Beat 1.1.1 / Zero Position</strong>)."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-7-3-3","title":"7.3.3: Contextual Recording Execution (Session vs. Arrangement)","blocks":[{"type":"step","title":"7.3.3: Contextual Recording Execution (Session vs. Arrangement)","blocks":[{"type":"prose","html":"In Ableton Live, pressing the physical <code>Record</code> button automatically targets the view currently in focus:"},{"type":"list","items":["<strong>Session View Active</strong>: Pressing <code>Record</code> engages <strong>Session Record</strong> (initiating overdub or recording into highlighted clip slots on armed tracks).","<strong>Arrangement View Active</strong>: Pressing <code>Record</code> engages <strong>Arrangement Record</strong> (punching in on the linear timeline)."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-7-3-4","title":"7.3.4: Dedicated Workflow Controls","blocks":[{"type":"step","title":"7.3.4: Dedicated Workflow Controls","blocks":[{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    DEDICATED WORKFLOW CONTROL MATRIX                          |\n+-------------------+---------------------+-------------------------------------+\n| Hardware Button   | Operational Action  | Technical Mechanism                 |\n+-------------------+---------------------+-------------------------------------+\n| **CAPTURE MIDI**  | Retrospective MIDI  | Recovers recently played MIDI notes |\n|                   | Capture             | played during playback without rec  |\n+-------------------+---------------------+-------------------------------------+\n| **QUANTISE**      | Real-Time Clip      | Applies DAW grid quantization       |\n|                   | Quantization        | to selected MIDI clip or last take  |\n+-------------------+---------------------+-------------------------------------+\n| **UNDO**          | DAW Undo            | Reverses the last software action   |\n| *(Shift + Undo)*  | *(DAW Redo)*        | Re-applies undone action (Redo)     |\n+-------------------+---------------------+-------------------------------------+\n| **METRONOME**     | Click Track Toggle  | Enables/disables DAW metronome audio|\n+-------------------+---------------------+-------------------------------------+</pre>"}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: Complete transport matrix; double-press Stop returns to 1.1.1; Session vs Arrangement record targeting; Capture MIDI retrospective capture; Quantise; Undo / Redo (<code>Shift+Undo</code>); Metronome toggle.","<strong>mustNotCover</strong>: Invention of undocumented Shift+Record combinations."],"ordered":false}]},{"type":"step","title":"Practical Guided Task & Assessment Checkpoint","blocks":[{"type":"prose","html":"<strong>Task</strong>: In your connected DAW, initiate playback with <code>Play</code>, stop playback with <code>Stop</code>, and press <code>Stop</code> a second time to verify the playhead returns to Beat 1.1.1. Play a phrase on the keys without recording, press <code>Capture MIDI</code>, and verify a new MIDI clip is automatically created containing your phrase."},{"type":"prose","html":"<strong>Checkpoint Validation</strong>:"},{"type":"list","items":["Second press of Stop returns playhead to timeline start.","Capture MIDI generates a populated MIDI clip in the DAW.","<code>Undo</code> and <code>Shift + Undo</code> (Redo) execute successfully from the hardware."],"ordered":false}]}],"minutes":8}],"exercises":[]},{"id":"launchkey-m-7-4-4","code":"7.4","title":"Continuous Encoders, Faders & DAW Control Surface","blurb":"Navigating large multi-track DAW arrangements requires rapid switching between individual track focus and multi-track 8-channel control banks. The Launchkey MK4 61 provides a dedicated dual-layer navigation protocol using the Track < and Tr","outcomes":[],"sources":[],"practiceFocus":[],"checkpoints":[],"lessons":[{"id":"launchkey-l-o-22","title":"Section overview","blocks":[{"type":"step","title":"Section 7.4 — Track Navigation, Focus & Banking Architecture","blocks":[{"type":"heading","text":"Module Overview","level":3},{"type":"prose","html":"Navigating large multi-track DAW arrangements requires rapid switching between individual track focus and multi-track 8-channel control banks. The Launchkey MK4 61 provides a dedicated dual-layer navigation protocol using the <code>Track &lt;</code> and <code>Track &gt;</code> hardware buttons."},{"type":"heading","text":"Learning Objectives","level":3},{"type":"list","items":["Execute single-track incremental navigation using <code>Track &lt;</code> and <code>Track &gt;</code>.","Execute 8-channel mixer banking using <code>Shift + Track &lt; &gt;</code>.","Formulate the definition of an 8-channel control bank across hardware faders, fader buttons, and continuous encoders.","Interpret boundary limit LED extinguishing.","Complete Assessment Gate F."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-7-4-1","title":"7.4.1: Single-Track Incremental Navigation","blocks":[{"type":"step","title":"7.4.1: Single-Track Incremental Navigation","blocks":[{"type":"prose","html":"Positioned below the OLED display are the <code>Track &lt;</code> and <code>Track &gt;</code> buttons:"},{"type":"prose","html":"<pre style=\"white-space:pre-wrap;font-family:ui-monospace,monospace\">+-------------------------------------------------------------------------------+\n|                    TRACK NAVIGATION PROTOCOL MATRIX                           |\n+-------------------+---------------------+-------------------------------------+\n| Hardware Command  | Navigation Step     | Resulting Hardware / DAW State      |\n+-------------------+---------------------+-------------------------------------+\n| **[ Track &lt; ]**   | **Previous Track**  | Moves DAW track focus 1 track LEFT  |\n| **[ Track &gt; ]**   | **Next Track**      | Moves DAW track focus 1 track RIGHT |\n+-------------------+---------------------+-------------------------------------+\n| **[ Shift ] +**   | **Bank 8 Tracks**   | Shifts active 8-fader mixer block   |\n| **[ Track &lt; ]**   | **LEFT**            | (e.g., Tracks 9–16 -&gt; Tracks 1–8)   |\n+-------------------+---------------------+-------------------------------------+\n| **[ Shift ] +**   | **Bank 8 Tracks**   | Shifts active 8-fader mixer block   |\n| **[ Track &gt; ]**   | **RIGHT**           | (e.g., Tracks 1–8 -&gt; Tracks 9–16)   |\n+-------------------+---------------------+-------------------------------------+</pre>"},{"type":"list","items":["<strong>OLED Feedback</strong>: Pressing <code>Track &lt;</code> or <code>Track &gt;</code> immediately updates the screen with the selected track's name and track index number (e.g., <code>Track 3: Lead Synth</code>).","<strong>DAW Soft-Arming</strong>: In Ableton Live, selecting a track via <code>Track &lt; &gt;</code> automatically applies soft-arming, routing keybed input to that track instantly."],"ordered":true}]}],"minutes":8},{"id":"launchkey-l-7-4-2","title":"7.4.2: 8-Channel Control Banking Architecture","blocks":[{"type":"step","title":"7.4.2: 8-Channel Control Banking Architecture","blocks":[{"type":"prose","html":"When working in projects with more than 8 tracks:"},{"type":"list","items":["<strong>Definition of an 8-Track Bank</strong>: The specific contiguous block of 8 DAW tracks currently mapped to <strong>Faders 1–8</strong>, <strong>Fader Buttons 1–8</strong>, and <strong>Mixer Encoders 1–8</strong>.","<strong>Executing Bank Shift</strong>: Holding <code>Shift</code> and pressing <code>Track &gt;</code> shifts the entire physical mixer surface by 8 tracks. The OLED screen displays <code>Mixer: Tracks 9–16</code>.","<strong>Fader Realignment</strong>: Faders 1–8 instantly decouple from Tracks 1–8 and take command of Tracks 9–16."],"ordered":false}]}],"minutes":8},{"id":"launchkey-l-7-4-3","title":"7.4.3: Visual Boundary Limit Feedback","blocks":[{"type":"step","title":"7.4.3: Visual Boundary Limit Feedback","blocks":[{"type":"list","items":["When the first track (Track 1) of a DAW project is focused, the <code>Track &lt;</code> button LED <strong>completely extinguishes</strong>.","When the final track of a DAW project is reached, the <code>Track &gt;</code> button LED <strong>completely extinguishes</strong>.","This provides tactile visual confirmation that the project boundary has been reached without requiring the user to look at the computer monitor."],"ordered":false}]},{"type":"step","title":"Operational Rules Summary","blocks":[{"type":"list","items":["<strong>mustCover</strong>: Single track move (<code>Track &lt; &gt;</code>); 8-channel bank move (<code>Shift + Track &lt; &gt;</code>); bank definition across faders and encoders; OLED feedback; boundary limit unlit states.","<strong>mustNotCover</strong>: Unofficial cheat sheets claiming single-track moves require Shift (the User Guide mandates single-track is unshifted, banking requires Shift)."],"ordered":false}]},{"type":"step","title":"Assessment Gate F (Encoders, Faders & Transport Validation)","blocks":[{"type":"prose","html":"<strong>Objective</strong>: Demonstrate complete operational mastery of the continuous rotary encoder modes, linear fader modes, transport controls, and track navigation."},{"type":"prose","html":"<strong>Self-Assessment Checklist</strong>:"},{"type":"list","items":["[ ] Recite all 8 encoder modes from memory (<code>Shift + Pads 1–8</code>): Plugin, Mixer, Sends, Transport, Custom 1, Custom 2, Custom 3, Custom 4.","[ ] Recite all 5 fader modes from memory (<code>Shift + Fader Buttons 1–5</code>): Volume, Custom 1, Custom 2, Custom 3, Custom 4.","[ ] Demonstrate Play, Pause (<code>Shift + Play</code>), Stop, and Double-Press Stop (Return to Beat 1.1.1).","[ ] In DAW Volume mode, move Fader 9 to control Master Volume, and press Fader Button 9 to alternate between Track Select and Track Arm states.","[ ] In a project with &gt;8 tracks, bank the mixer surface using <code>Shift + Track &gt;</code> and confirm Faders 1–8 control Tracks 9–16."],"ordered":true}]}],"minutes":8}],"exercises":[]}]};
